import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * The privacy policy and terms of use, as the app fetches them (`GET /v1/legal`). The app keeps its own
 * copy in its string resources (`legal_*`); `legal-texts.json` is the same text, generated by
 * `scripts/build-legal-texts.mjs`, and `test/legal.test.js` fails when the two differ.
 *
 * [LEGAL_VERSION] must equal `LegalTerms.VERSION` in the app. Raise both together when the meaning of the
 * text changes: the app then asks every user to accept again.
 */
export const LEGAL_VERSION = 9;

/** The sections in the order the app shows them. */
export const LEGAL_KEYS = ['what', 'privacy', 'stored', 'sent', 'rights', 'terms', 'liability', 'changes', 'contact'];

const LANGUAGES = ['de', 'en'];

const HERE = dirname(fileURLToPath(import.meta.url));
export const LEGAL_TEXTS_FILE = join(HERE, 'legal-texts.json');

/** Undoes the escaping of an Android string resource (`\n`, `\'`, `&amp;`), so the text reads as the app shows it. */
export function unescapeAndroid(raw) {
  const entities = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };
  const escapes = { n: '\n', t: '\t', "'": "'", '"': '"', '\\': '\\', '@': '@', '?': '?' };
  return raw
    .replace(/&(amp|lt|gt|quot|apos);/g, (_, name) => entities[name])
    .replace(/\\(.)/g, (_, char) => escapes[char] ?? char);
}

/** The legal sections of one `strings.xml`, in [LEGAL_KEYS] order. Throws when a section is missing. */
export function legalSectionsFromStrings(xml) {
  const found = new Map();
  const pattern = /<string name="legal_([a-z]+)_(title|body)">([\s\S]*?)<\/string>/g;
  for (const match of xml.matchAll(pattern)) {
    const [, key, part, raw] = match;
    if (!LEGAL_KEYS.includes(key)) continue;
    const entry = found.get(key) ?? {};
    entry[part] = unescapeAndroid(raw);
    found.set(key, entry);
  }
  return LEGAL_KEYS.map((key) => {
    const entry = found.get(key);
    if (!entry?.title || !entry?.body) throw new Error(`legal section ${key} is missing`);
    return { key, title: entry.title, body: entry.body };
  });
}

let cached;

/** The texts as the server serves them: { version, languages: { de: [...], en: [...] } }. Read once. */
export async function loadLegalTexts(file = LEGAL_TEXTS_FILE) {
  if (cached && file === LEGAL_TEXTS_FILE) return cached;
  const parsed = JSON.parse(await readFile(file, 'utf8'));
  if (parsed.version !== LEGAL_VERSION) throw new Error(`legal-texts.json is version ${parsed.version}, expected ${LEGAL_VERSION}`);
  for (const language of LANGUAGES) {
    if (!Array.isArray(parsed.languages?.[language])) throw new Error(`legal-texts.json has no ${language} texts`);
  }
  if (file === LEGAL_TEXTS_FILE) cached = parsed;
  return parsed;
}

/** The answer for one language: unknown languages get German, the language of the policy. */
export function legalAnswer(texts, lang) {
  const language = lang === 'en' ? 'en' : 'de';
  return { version: texts.version, lang: language, sections: texts.languages[language] };
}

export { LANGUAGES };
